	function goStore(item){
		if(hide_mer_status.value == 0){
			uni.navigateTo({
				url:`/views/pages/home/store?mer_id=${item.merchant.mer_id}`
			})
		}				
	}
	function goPage(id){
		uni.navigateTo({
			url:'/pagesOrder/refund/goods/index?id='+id
		})
	}
	function bindTab(index){
		tab_index.value = index
		page.value =1
		is_scroll.value = true
		goods_list.value = []
		getList()
	}
	function getList(){
		if(!is_scroll.value) return
		refundListApi({
			type:tab_index.value,
			page:page.value,
			page_size:page_size.value
		}).then(({data})=>{
			is_scroll.value = data.items.length>=page_size.value
			goods_list.value = goods_list.value.concat(data.items)
			console.log('data',goods_list.value)
			page.value+=1
		})
	}
	// 去详情页
	function goDetail(item){
		uni.navigateTo({
			url:'/pagesOrder/refund/detail?id='+item.refund_order_id
		})
	}
	// 删除记录
	function bindDetele(item,index){
		uni.showModal({
			title: '提示',
			content: '确定删除该记录吗？',
			success: function (res) {
				if (res.confirm) {
						refundDelApi({ refund_order_id: item.refund_order_id }).then(res=>{
							goods_list.value.splice(index,1)
						})
						uni.showToast({
							title:'删除成功',
							icon:'none'
						})
				} else if (res.cancel) {
					console.log('用户点击取消');
				}
			}
		});
		
	}
	
	
